dashboard.definition:
{
    "title": "ThousandEyes Network Intelligence",
    "description": "ThousandEyes tests across all agents",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        },
        "input_site": {
            "type": "input.dropdown",
            "title": "Site",
            "options": {
                "items": [
                    {
                        "label": "All sites",
                        "value": "*"
                    },
                    {
                        "label": "Atlanta",
                        "value": "atlanta"
                    },
                    {
                        "label": "Berlin",
                        "value": "berlin"
                    },
                    {
                        "label": "Vienna",
                        "value": "vienna"
                    }
                ],
                "token": "site",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_pulse": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_cisco_catalyst sourcetype=\"cisco:dnac:devicehealth\") OR (index=demo_mes production_rate_per_hour=*) OR (index=demo_cisco_meraki sourcetype=\"meraki:wirelessdevicespacketlossbydevice\")\n| rex field=Location \"(?i)(?<cat_site>vienna|berlin|atlanta)\"\n| rex field=network.name \"(?i)^(?<mer_site>vienna|berlin|atlanta)\"\n| eval site=lower(coalesce(cat_site, mer_site, location))\n| stats avg(HealthScore) as campus dc(DeviceName) as devices dc(eval(if(Reachability!=\"Reachable\", DeviceName, null()))) as unreachable avg(oee_pct) as oee avg(downstream.lossPercentage) as wifi by site\n| where site IN (\"atlanta\", \"berlin\", \"vienna\")\n| eval score=round(campus * 10, 0)\n| eval status=case(unreachable > devices / 2 OR campus < 5, \"crit\", unreachable > 0 OR campus < 8 OR wifi > 2 OR oee < 70, \"warn\", isnotnull(campus), \"ok\")\n| eval detail=\"Campus \".round(campus, 1).\" · \".unreachable.\" of \".devices.\" devices unreachable · Wi-Fi loss \".round(wifi, 1).\" % · OEE \".round(oee, 0).\" %\"\n| append [search index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=agent-to-agent earliest=-5m latest=now\n| stats avg(metric_name:network.loss) as loss avg(metric_name:network.latency) as latency by thousandeyes.agent.location thousandeyes.target.agent.location\n| rename thousandeyes.agent.location as site thousandeyes.target.agent.location as to\n| eval loss=round(loss, 2), latency_ms=round(latency * 1000, 0)\n| fields site to loss latency_ms]\n| append [| mstats avg(_value) as aborted WHERE index=demo_vmware_metrics metric_name=\"vmware.vm.gpu.llm.requests.aborted.pct\" location=\"frankfurt\" earliest=-5m latest=now\n| eval site=\"frankfurt\", score=round(100 - aborted, 0), detail=\"DC Frankfurt · GPU cluster · \".round(aborted, 1).\" % aborted LLM requests\"]\n| table site to score status loss latency_ms detail",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-5m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "Site mesh (live)"
        },
        "ds_base": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" \"thousandeyes.agent.location\"=\"$site$\"\n| eval type='thousandeyes.test.type', test='thousandeyes.test.name', agent='thousandeyes.agent.location'\n| bin _time span=5m\n| stats count avg(metric_name:dns.lookup.availability) as dns_avail avg(metric_name:dns.lookup.duration) as dns_s avg(metric_name:http.server.request.availability) as http_avail avg(metric_name:http.client.request.duration) as http_s avg(metric_name:http.server.throughput) as http_bps avg(metric_name:network.latency) as latency_s avg(metric_name:network.loss) as loss avg(metric_name:network.jitter) as jitter by _time type test agent",
                "enableSmartSources": true
            },
            "name": "ThousandEyes tests (5 min)"
        },
        "ds_k_dns": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"dns-server\" | timechart span=5m avg(dns_avail) as \"DNS availability\""
            }
        },
        "ds_k_dns_ms": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"dns-server\" | eval ms=dns_s * 1000 | timechart span=5m avg(ms) as \"DNS duration\""
            }
        },
        "ds_k_http": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"http-server\" | timechart span=5m avg(http_avail) as \"HTTP availability\""
            }
        },
        "ds_k_http_ms": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"http-server\" | eval ms=http_s * 1000 | timechart span=5m avg(ms) as \"HTTP response\""
            }
        },
        "ds_k_jitter": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"agent-to-server\" | timechart span=5m avg(jitter) as \"Teams jitter\""
            }
        },
        "ds_k_loss": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type IN (\"agent-to-agent\", \"agent-to-server\") | timechart span=5m avg(loss) as \"Packet loss\""
            }
        },
        "ds_heat_latency": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"agent-to-agent\" | eval ms=latency_s * 1000 | timechart span=5m limit=0 avg(ms) by test"
            }
        },
        "ds_volume": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| timechart span=5m sum(count) by type"
            }
        },
        "ds_http": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"http-server\"\n| stats avg(http_avail) as \"Availability %\" avg(http_s) as s avg(http_bps) as bps by test agent\n| eval \"Response ms\"=round(s * 1000, 0), \"Availability %\"=round('Availability %', 2), \"Throughput MB/s\"=round(bps / 1048576, 2)\n| table test agent \"Availability %\" \"Response ms\" \"Throughput MB/s\"\n| rename test as Test agent as Agent"
            }
        },
        "ds_teams": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where test=\"Teams Media Quality\"\n| stats avg(latency_s) as s avg(loss) as \"Loss %\" avg(jitter) as \"Jitter ms\" by agent\n| eval \"Latency ms\"=round(s * 1000, 1), \"Loss %\"=round('Loss %', 2), \"Jitter ms\"=round('Jitter ms', 1)\n| table agent \"Latency ms\" \"Loss %\" \"Jitter ms\"\n| rename agent as Agent"
            }
        },
        "ds_dns": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_base",
                "query": "| where type=\"dns-server\" | eval ms=dns_s * 1000 | stats avg(ms) as \"DNS ms\" by agent | eval \"DNS ms\"=round('DNS ms', 1)"
            }
        },
        "ds_bgp": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=bgp \"thousandeyes.agent.location\"=\"$site$\"\n| stats latest(bgp.prefix) as Prefix latest(bgp.as_path) as \"AS path\" latest(metric_name:bgp.reachability) as \"Reachability %\" min(metric_name:bgp.reachability) as \"Min reachability %\" sum(metric_name:bgp.path_changes.count) as \"Path changes\" sum(metric_name:bgp.updates.count) as Updates by thousandeyes.agent.location\n| rename thousandeyes.agent.location as \"Vantage point\"",
                "enableSmartSources": true
            },
            "name": "BGP"
        },
        "ds_wt": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" thousandeyes.test.type=web-transaction \"thousandeyes.agent.location\"=\"$site$\"\n| stats avg(metric_name:web.transaction.completion) as \"Completion %\" sum(metric_name:web.transaction.errors.count) as Errors avg(metric_name:web.transaction.duration) as \"Duration s\" by thousandeyes.agent.location\n| eval \"Completion %\"=round('Completion %', 1), \"Duration s\"=round('Duration s', 2)\n| rename thousandeyes.agent.location as Agent",
                "enableSmartSources": true
            },
            "name": "B2B order transaction"
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
