        "viz_sub_cs_thousandeyes": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/sub_cs_thousandeyes_on.svg",
                "preserveAspectRatio": true
            }
        },
        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_dns"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 2,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 98,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 98,
                        "to": 99.5,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 99.5,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_dns_ms"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 1,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 100,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 100,
                        "to": 250,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 250,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_http"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 2,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 95,
                        "value": "#ff4d6d"
                    },
                    {
                        "from": 95,
                        "to": 99,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 99,
                        "value": "#34e2a0"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_http_ms"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 500,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 500,
                        "to": 1500,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 1500,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_05": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_jitter"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
