                "unit": "ms",
                "unitPosition": "after"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 30,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 30,
                        "to": 50,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 50,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_06": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_loss"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 2,
                "sparklineStrokeColor": "#22d3ee",
                "unit": "%",
                "unitPosition": "after"
            },
            "context": {
