                    {
                        "to": 1,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 1,
                        "to": 3,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 3,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_07": {
            "type": "coolashaker_studio.pulse_map",
            "dataSources": {
                "primary": "ds_pulse"
            },
            "options": {
                "view": "atlantic",
                "drilldownToken": "site"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_thousandeyes",
                        "tokens": [
                            {
                                "token": "site",
                                "value": "value"
                            }
                        ],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_08": {
            "type": "coolashaker_studio.heat_timeline",
            "dataSources": {
                "primary": "ds_heat_latency"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 150,
                "crit": 300,
                "unit": "ms",
                "decimals": 0
            }
        },
        "viz_09": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_http"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 9,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Availability %": {
                        "rowBackgroundColors": "> table | seriesByName(\"Availability %\") | rangeValue(range_2)"
                    },
                    "Response ms": {
                        "rowBackgroundColors": "> table | seriesByName(\"Response ms\") | rangeValue(range_3)"
                    }
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ],
                "range_2": [
                    {
                        "to": 95,
                        "value": "#5a1426"
                    },
                    {
                        "from": 95,
                        "to": 99,
                        "value": "#4d3a08"
                    },
                    {
                        "from": 99,
                        "value": "#0d3b2c"
                    }
                ],
                "range_3": [
                    {
                        "to": 500,
                        "value": "#0d3b2c"
                    },
